import type * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

// 像素约定：竖线是 GridContainer 的 border-x（位于内容区外 1px），
// 上方横线是上一行的底线（同样在外 1px），本行底线由 screen-line-bottom 画在内侧最后 1px。
// 十字为 11px 方框，线在第 5 px，所以用整数偏移让中心正好压在线条像素上，不用 translate(-50%)。
const gridCrosshairVariants = cva(
  "pointer-events-none absolute z-10 size-[11px] before:absolute before:inset-y-0 before:left-[5px] before:w-px before:bg-foreground/45 after:absolute after:inset-x-0 after:top-[5px] after:h-px after:bg-foreground/45",
  {
    variants: {
      /**
       * 十字所在的角：top-left、top-right、bottom-left、bottom-right
       * @default "top-left"
       */
      position: {
        "top-left": "-top-[6px] -left-[6px]",
        "top-right": "-top-[6px] -right-[6px]",
        "bottom-left": "-bottom-[5px] -left-[6px]",
        "bottom-right": "-right-[6px] -bottom-[5px]",
      },
      /**
       * 十字的定位基准。line：底线由 screen-line-bottom 画在元素内侧（GridSection / GridSeparator）；border：元素自身有四边 border
       * @default "line"
       */
      anchor: { line: "", border: "" },
    },
    compoundVariants: [
      { anchor: "border", position: "bottom-left", className: "-bottom-[6px]" },
      {
        anchor: "border",
        position: "bottom-right",
        className: "-bottom-[6px]",
      },
    ],
    defaultVariants: { position: "top-left", anchor: "line" },
  },
)

// 纹理层：高 31px（不覆盖底线），左端在左竖线外 4096px，平铺原点因此正好落在竖线上
const gridSeparatorVariants = cva(
  "absolute top-0 bottom-px -left-[4097px] -right-[4096px]",
  {
    variants: {
      pattern: {
        ruler: "pattern-ruler",
        hatch: "pattern-hatch",
        dots: "pattern-dots",
        grid: "pattern-grid",
        plus: "pattern-plus",
        wave: "pattern-wave",
        none: "",
      },
    },
    defaultVariants: { pattern: "dots" },
  },
)

type GridSeparatorPattern = NonNullable<
  VariantProps<typeof gridSeparatorVariants>["pattern"]
>

/**
 * 交点十字：绘制在容器竖线与横线交点处的小「+」，纯装饰。
 * 放在带 `position: relative` 的行（GridSection、GridSeparator）内，由 position 指定四个角之一。
 */
function GridCrosshair({
  className,
  position,
  anchor,
  ...props
}: React.ComponentProps<"span"> & VariantProps<typeof gridCrosshairVariants>) {
  return (
    <span
      aria-hidden
      data-slot="grid-crosshair"
      data-position={position ?? "top-left"}
      className={cn(gridCrosshairVariants({ position, anchor }), className)}
      {...props}
    />
  )
}

/**
 * 页面主容器：固定宽度 + 左右竖线。
 * 宽度可通过 CSS 变量 --grid-width 覆盖（默认 48rem）。
 * 外宽多 1px，使左右两条竖线的间距正好等于 --grid-width（纹路周期都能整除它）。
 */
function GridContainer({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-container"
      className={cn(
        "mx-auto w-full max-w-[calc(var(--grid-width,48rem)+1px)] border-x border-edge",
        className,
      )}
      {...props}
    />
  )
}

/**
 * 一行内容：底部一条横跨整个屏幕的分隔线。
 * 放在 GridContainer 内使用。
 */
function GridSection({
  className,
  topLine = false,
  crosshair = false,
  children,
  ...props
}: React.ComponentProps<"section"> & {
  /**
   * 在行的顶部补一条全屏横线（默认只画底线）
   * @default false
   */
  topLine?: boolean
  /**
   * 在底线与左右竖线的两个交点处绘制「+」
   * @default false
   */
  crosshair?: boolean
}) {
  return (
    <section
      data-slot="grid-section"
      data-top-line={topLine}
      className={cn(
        "screen-line-bottom",
        topLine && "screen-line-top",
        className,
      )}
      {...props}
    >
      {children}
      {crosshair ? (
        <>
          <GridCrosshair position="bottom-left" />
          <GridCrosshair position="bottom-right" />
        </>
      ) : null}
    </section>
  )
}

/**
 * 分隔带：全屏宽度的纹理 + 底部横线，用于主题切换处。
 * 默认是点阵纹路；需要时可用 crosshair 在交点绘制「+」。
 */
function GridSeparator({
  className,
  pattern,
  label,
  crosshair,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof gridSeparatorVariants> & {
    /**
     * 纹路：dots、ruler、hatch、grid、plus、wave，none 为只留线条
     * @default "dots"
     */
    pattern?: GridSeparatorPattern | null
    /** 左侧的等宽小字编号（如 `02 / PROJECTS`），像标签一样贴在纹路上；可与任意纹路组合 */
    label?: React.ReactNode
    /**
     * 是否在四个交点绘制十字
     * @default false
     */
    crosshair?: boolean
  }) {
  const resolved = pattern ?? "dots"
  const showCrosshair = crosshair ?? false
  return (
    <div
      aria-hidden
      data-slot="grid-separator"
      data-pattern={resolved}
      className={cn("screen-line-bottom h-8 w-full", className)}
      {...props}
    >
      {resolved === "ruler" ? (
        // 刻度尺带一层极淡的底色，让分隔带读作一条「带子」
        <div className="absolute top-0 -right-[4096px] bottom-px -left-[4097px] bg-foreground/[0.025]" />
      ) : null}
      <div
        data-slot="grid-separator-pattern"
        className={gridSeparatorVariants({ pattern: resolved })}
      />
      {label ? (
        <div
          data-slot="grid-separator-label"
          className="absolute inset-y-0 left-4 flex items-center sm:left-6"
        >
          <span className="bg-background px-1.5 font-mono text-[11px] leading-4 tracking-[0.08em] whitespace-nowrap text-muted-foreground">
            {label}
          </span>
        </div>
      ) : null}
      {showCrosshair ? (
        <>
          <GridCrosshair position="top-left" />
          <GridCrosshair position="top-right" />
          <GridCrosshair position="bottom-left" />
          <GridCrosshair position="bottom-right" />
        </>
      ) : null}
    </div>
  )
}

/**
 * 分栏：栏与栏之间用虚线分隔，窄屏自动堆叠。
 */
function GridColumns({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-columns"
      className={cn(
        "grid grid-cols-1 divide-y divide-dashed divide-edge sm:grid-cols-2 sm:divide-x sm:divide-y-0",
        className,
      )}
      {...props}
    />
  )
}

export {
  GridColumns,
  GridContainer,
  GridCrosshair,
  GridSection,
  GridSeparator,
  gridCrosshairVariants,
  gridSeparatorVariants,
}
export type { GridSeparatorPattern }

"use client"

import { useMemo, useState } from "react"

import { cn } from "@/lib/utils"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

const levels = [
  "bg-foreground/5",
  "bg-foreground/20",
  "bg-foreground/40",
  "bg-foreground/60",
  "bg-foreground/80",
]
const dayMilliseconds = 86_400_000
// 星期表头只标注一、三、五，保持与方块行错位的斑马排布。
const weekdayRows = [1, 3, 5]
const weekStart = Date.UTC(2024, 0, 7) // 2024-01-07 是周日

/** 单日记录；`level` 只决定方块深浅，语义始终由 `count` 提供。 */
type Contribution = { date: string; count: number; level: number }

/** 按真实日期排列的贡献日历；空缺日期不冒充零贡献，数据表提供非颜色读取方式。 */
function ContributionGraph({
  data,
  className,
  locale = "zh-CN",
  lessLabel = "少",
  moreLabel = "多",
  legendLabel = "贡献数量由少到多",
  unitLabel = "次贡献",
  emptyLabel = "贡献日历暂未更新。下次构建时会自动重试获取数据。",
  regionLabel = "过去一年的 GitHub 贡献日历，可横向滚动；方向键查看相邻日期",
  detailsLabel = "查看每日贡献数据",
  captionLabel = "过去一年的每日贡献记录",
  dateHeadingLabel = "日期",
  countHeadingLabel = "贡献次数",
}: {
  /** 过去一年的每日记录，顺序任意；只绘制最后一天往前 365 天 */
  data: readonly Contribution[]
  /** 附加到根元素的样式类名 */
  className?: string
  /**
   * BCP 47 区域标识，决定月份、星期与数字的格式化方式
   * @default "zh-CN"
   */
  locale?: string
  /**
   * 图例起点文字
   * @default "少"
   */
  lessLabel?: string
  /**
   * 图例终点文字
   * @default "多"
   */
  moreLabel?: string
  /**
   * 图例的读屏说明
   * @default "贡献数量由少到多"
   */
  legendLabel?: string
  /**
   * 计数的单位，用于读屏标签与悬浮提示
   * @default "次贡献"
   */
  unitLabel?: string
  /**
   * 没有有效数据时的提示，说明下次构建会重试
   * @default "贡献日历暂未更新。下次构建时会自动重试获取数据。"
   */
  emptyLabel?: string
  /**
   * 可滚动区域的说明，供读屏使用
   * @default "过去一年的 GitHub 贡献日历，可横向滚动；方向键查看相邻日期"
   */
  regionLabel?: string
  /**
   * 数据表折叠标题
   * @default "查看每日贡献数据"
   */
  detailsLabel?: string
  /**
   * 数据表的读屏标题
   * @default "过去一年的每日贡献记录"
   */
  captionLabel?: string
  /**
   * 数据表表头：日期列
   * @default "日期"
   */
  dateHeadingLabel?: string
  /**
   * 数据表表头：数量列
   * @default "贡献次数"
   */
  countHeadingLabel?: string
}) {
  const [activeDate, setActiveDate] = useState<string | null>(null)
  const formatters = useMemo(
    () => ({
      date: new Intl.DateTimeFormat(locale, {
        timeZone: "UTC",
        year: "numeric",
        month: "long",
        day: "numeric",
      }),
      month: new Intl.DateTimeFormat(locale, {
        timeZone: "UTC",
        month: "short",
      }),
      weekday: new Intl.DateTimeFormat(locale, {
        timeZone: "UTC",
        weekday: "narrow",
      }),
      number: new Intl.NumberFormat(locale),
    }),
    [locale],
  )
  const { weeks, entries } = useMemo(() => {
    const valid = data
      .filter(
        (entry) =>
          /^\d{4}-\d{2}-\d{2}$/.test(entry.date) &&
          Number.isFinite(Date.parse(entry.date)),
      )
      .toSorted((a, b) => a.date.localeCompare(b.date))
    if (!valid.length) return { weeks: [], entries: [] }
    const end = Date.parse(valid[valid.length - 1].date)
    const start = end - 364 * dayMilliseconds
    const firstSunday = start - new Date(start).getUTCDay() * dayMilliseconds
    const entries = valid.filter((entry) => Date.parse(entry.date) >= start)
    const byDate = new Map(entries.map((entry) => [entry.date, entry]))
    const weeks: {
      date: string
      day: Contribution | undefined
      month: string | null
    }[][] = []
    for (let stamp = firstSunday; stamp <= end; stamp += dayMilliseconds) {
      const date = new Date(stamp).toISOString().slice(0, 10)
      const weekIndex = Math.floor(
        (stamp - firstSunday) / (7 * dayMilliseconds),
      )
      const day = new Date(stamp)
      if (!weeks[weekIndex]) weeks[weekIndex] = []
      weeks[weekIndex].push({
        date,
        day: byDate.get(date),
        month: day.getUTCDate() === 1 ? formatters.month.format(day) : null,
      })
    }
    return { weeks, entries }
  }, [data, formatters])

  if (!entries.length)
    return (
      <p
        data-slot="contribution-graph"
        data-state="empty"
        className={cn(
          "py-8 font-mono text-xs leading-6 text-muted-foreground",
          className,
        )}
      >
        {emptyLabel}
      </p>
    )
  return (
    <div
      data-slot="contribution-graph"
      data-state="ready"
      className={cn("min-w-0", className)}
    >
      <div
        data-slot="contribution-graph-scroll"
        role="region"
        aria-label={regionLabel}
        tabIndex={0}
        className="overflow-x-auto rounded-sm pb-2 focus-visible:outline-2 focus-visible:outline-ring"
      >
        <div className="flex w-max gap-2 font-mono text-[10px] text-muted-foreground">
          <div
            data-slot="contribution-graph-weekdays"
            aria-hidden="true"
            className="grid grid-rows-[18px_repeat(7,10px)] gap-[3px]"
          >
            <span />
            {Array.from({ length: 7 }, (_, index) => (
              <span key={index}>
                {weekdayRows.includes(index)
                  ? formatters.weekday.format(
                      new Date(weekStart + index * dayMilliseconds),
                    )
                  : null}
              </span>
            ))}
          </div>
          <TooltipProvider delay={100}>
            <div className="flex gap-[3px]">
              {weeks.map((week) => (
                <div
                  key={week[0].date}
                  className="grid w-[10px] grid-rows-[18px_repeat(7,10px)] gap-[3px]"
                >
                  <span
                    aria-hidden="true"
                    className="relative whitespace-nowrap"
                  >
                    {week.find((entry) => entry.month)?.month}
                  </span>
                  {week.map(({ date, day }) =>
                    day ? (
                      <Tooltip key={date}>
                        <TooltipTrigger
                          render={<button type="button" />}
                          data-slot="contribution-graph-day"
                          data-level={Math.max(
                            0,
                            Math.min(4, Math.floor(day.level)),
                          )}
                          tabIndex={
                            activeDate === date ||
                            (!activeDate && date === entries[0].date)
                              ? 0
                              : -1
                          }
                          onFocus={() => setActiveDate(date)}
                          onKeyDown={(event) => {
                            const offsets: Record<string, number> = {
                              ArrowDown: 1,
                              ArrowUp: -1,
                              ArrowLeft: -7,
                              ArrowRight: 7,
                            }
                            if (!(event.key in offsets)) return
                            event.preventDefault()
                            const position = entries.findIndex(
                              (entry) => entry.date === date,
                            )
                            const next =
                              entries[
                                Math.max(
                                  0,
                                  Math.min(
                                    entries.length - 1,
                                    position + offsets[event.key],
                                  ),
                                )
                              ]
                            const region =
                              event.currentTarget.closest('[role="region"]')
                            region
                              ?.querySelector<HTMLButtonElement>(
                                `[data-date="${next.date}"]`,
                              )
                              ?.focus()
                          }}
                          data-date={date}
                          aria-label={`${formatters.date.format(new Date(date))}：${formatters.number.format(day.count)} ${unitLabel}`}
                          className={cn(
                            "size-[10px] rounded-[2px] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
                            levels[
                              Math.max(0, Math.min(4, Math.floor(day.level)))
                            ] ?? levels[0],
                          )}
                        />
                        <TooltipContent>
                          {formatters.date.format(new Date(date))} ·{" "}
                          {formatters.number.format(day.count)} {unitLabel}
                        </TooltipContent>
                      </Tooltip>
                    ) : (
                      <span
                        key={date}
                        aria-hidden="true"
                        className="size-[10px]"
                      />
                    ),
                  )}
                </div>
              ))}
            </div>
          </TooltipProvider>
        </div>
      </div>
      <div
        data-slot="contribution-graph-legend"
        role="img"
        aria-label={legendLabel}
        className="mt-3 flex items-center justify-end gap-1.5 font-mono text-[10px] text-muted-foreground"
      >
        <span>{lessLabel}</span>
        {levels.map((level) => (
          <span
            key={level}
            aria-hidden="true"
            className={cn("size-2.5 rounded-[2px]", level)}
          />
        ))}
        <span>{moreLabel}</span>
      </div>
      <details
        data-slot="contribution-graph-details"
        className="mt-2 text-xs text-muted-foreground"
      >
        <summary className="w-fit cursor-pointer rounded py-1 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring">
          {detailsLabel}
        </summary>
        <div className="mt-2 max-h-48 overflow-auto">
          <table
            data-slot="contribution-graph-table"
            className="w-full text-left font-mono tabular-nums"
          >
            <caption className="sr-only">{captionLabel}</caption>
            <thead>
              <tr>
                <th scope="col" className="py-2 font-normal">
                  {dateHeadingLabel}
                </th>
                <th scope="col" className="py-2 text-right font-normal">
                  {countHeadingLabel}
                </th>
              </tr>
            </thead>
            <tbody>
              {entries.map((day) => (
                <tr key={day.date}>
                  <th scope="row" className="py-1 font-normal">
                    {day.date}
                  </th>
                  <td className="text-right">
                    {formatters.number.format(day.count)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </details>
    </div>
  )
}

export { ContributionGraph, type Contribution }

"use client"

import { useEffect, useState } from "react"

import { cn } from "@/lib/utils"

/** 以指定 IANA 时区显示时间，并比较访客当前的时区偏移。 */
function LocalTime({
  timeZone,
  className,
  locale = "zh-CN",
  placeholder = "--:--:--",
  placeholderLabel = "当地时间",
  sameTimeLabel = "与你同一时间",
  aheadLabel = "早",
  behindLabel = "晚",
  hourUnit = "小时",
}: {
  /** IANA 时区名，例如 `Asia/Shanghai`，不支持 `+08:00` 这类固定偏移 */
  timeZone: string
  /** 附加到根元素的样式类名 */
  className?: string
  /**
   * BCP 47 区域标识，决定时间与数字的格式
   * @default "zh-CN"
   */
  locale?: string
  /**
   * 挂载前的占位时间
   * @default "--:--:--"
   */
  placeholder?: string
  /**
   * 占位时间后的说明
   * @default "当地时间"
   */
  placeholderLabel?: string
  /**
   * 与访客时区相同时的说明
   * @default "与你同一时间"
   */
  sameTimeLabel?: string
  /**
   * 目标时区更早时的前缀
   * @default "早"
   */
  aheadLabel?: string
  /**
   * 目标时区更晚时的前缀
   * @default "晚"
   */
  behindLabel?: string
  /**
   * 时差的单位
   * @default "小时"
   */
  hourUnit?: string
}) {
  const [now, setNow] = useState<Date | null>(null)
  useEffect(() => {
    const update = () => setNow(new Date())
    const first = window.setTimeout(update, 0)
    const timer = window.setInterval(update, 1000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(timer)
    }
  }, [])

  if (!now)
    return (
      <span
        data-slot="local-time"
        data-state="pending"
        className={cn("tabular-nums", className)}
      >
        {placeholder}{" "}
        <span
          data-slot="local-time-note"
          className="text-muted-foreground"
        >{`// ${placeholderLabel}`}</span>
      </span>
    )
  const formatter = new Intl.DateTimeFormat(locale, {
    timeZone,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  })
  const zone =
    new Intl.DateTimeFormat("en-US", { timeZone, timeZoneName: "longOffset" })
      .formatToParts(now)
      .find((part) => part.type === "timeZoneName")?.value ?? "GMT"
  const offset = zone.match(/GMT([+-])(\d{2}):(\d{2})/)
  const targetMinutes = offset
    ? (Number(offset[2]) * 60 + Number(offset[3])) *
      (offset[1] === "+" ? 1 : -1)
    : 0
  const difference = (targetMinutes + now.getTimezoneOffset()) / 60
  const comparison =
    difference === 0
      ? sameTimeLabel
      : `${difference > 0 ? aheadLabel : behindLabel} ${new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(Math.abs(difference))} ${hourUnit}`
  return (
    <span
      data-slot="local-time"
      data-state="ready"
      className={cn("tabular-nums", className)}
    >
      <time data-slot="local-time-time" dateTime={now.toISOString()}>
        {formatter.format(now)}
      </time>{" "}
      <span
        data-slot="local-time-note"
        className="text-muted-foreground"
      >{`// ${comparison}`}</span>
    </span>
  )
}

export { LocalTime }

"use client"

import { useEffect, useState } from "react"

/** 根据访客当地时间问候，首屏使用一致的静态文案以避免水合差异。 */
function Greeting({
  fallback = "你好",
  suffix = "，很高兴在这里遇见你。",
  morning = "早上好",
  noon = "中午好",
  afternoon = "下午好",
  evening = "晚上好",
}: {
  /**
   * 首屏与挂载前显示的静态文案，需保持中性以避免水合差异
   * @default "你好"
   */
  fallback?: string
  /**
   * 问候语之后拼接的文本
   * @default "，很高兴在这里遇见你。"
   */
  suffix?: string
  /**
   * 05:00–10:59 的问候语
   * @default "早上好"
   */
  morning?: string
  /**
   * 11:00–13:59 的问候语
   * @default "中午好"
   */
  noon?: string
  /**
   * 14:00–17:59 的问候语
   * @default "下午好"
   */
  afternoon?: string
  /**
   * 18:00–次日 04:59 的问候语
   * @default "晚上好"
   */
  evening?: string
}) {
  // 只保存小时数：挂载前为 null，用它区分服务端静态文案与客户端时段文案。
  const [hour, setHour] = useState<number | null>(null)
  useEffect(() => {
    const update = () => setHour(new Date().getHours())
    const first = window.setTimeout(update, 0)
    const timer = window.setInterval(update, 60_000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(timer)
    }
  }, [])
  const greeting =
    hour === null
      ? fallback
      : hour >= 5 && hour < 11
        ? morning
        : hour >= 11 && hour < 14
          ? noon
          : hour >= 14 && hour < 18
            ? afternoon
            : evening
  return (
    <span data-slot="greeting" data-state={hour === null ? "pending" : "ready"}>
      {greeting}
      {suffix}
    </span>
  )
}

