"use client"

import { useCallback, useState, type FormEvent } from "react"
import type { z } from "zod"

import { DEFAULT_LABELS } from "./config"

type FieldErrors = Record<string, string>
// 字面量初始值（false、""）会被推断成字面量类型，这里放宽为 boolean / string
type Widen<T> = {
  [K in keyof T]: T[K] extends boolean ? boolean : T[K] extends string ? string : T[K]
}

/** 每个字段只保留第一条错误，避免一次堆出一长串提示 */
function toErrors(error: z.ZodError): FieldErrors {
  const errors: FieldErrors = {}
  for (const issue of error.issues) {
    const key = String(issue.path[0] ?? "")
    if (key && !(key in errors)) errors[key] = issue.message
  }
  return errors
}

/** 把未知错误转成可展示的中文文案；没有 message 时用传入的兜底文案。 */
function errorMessage(
  error: unknown,
  fallback: string = DEFAULT_LABELS.requestFailed,
) {
  return error instanceof Error && error.message ? error.message : fallback
}

/** 包装一个异步动作：管理 loading，并把抛出的错误转成可展示的中文文案。 */
function useAsyncAction(fallbackError: string = DEFAULT_LABELS.requestFailed) {
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const run = useCallback(
    async (action: () => Promise<void>) => {
      setPending(true)
      setError(null)
      try {
        await action()
        return true
      } catch (caught) {
        setError(errorMessage(caught, fallbackError))
        return false
      } finally {
        setPending(false)
      }
    },
    [fallbackError],
  )
  return { pending, error, run, clearError: () => setError(null) }
}

/**
 * 极简受控表单：zod 校验 + 字段错误 + 提交状态。
 * 首次提交前，字段失焦时校验该字段；提交失败后，输入时实时重新校验。
 */
function useAuthForm<I extends Record<string, string | boolean>>(
  schema: z.ZodType,
  initial: I,
  options: { fallbackError?: string } = {},
) {
  type V = Widen<I>
  const [values, setValues] = useState<V>(initial as V)
  const [errors, setErrors] = useState<FieldErrors>({})
  const [submitted, setSubmitted] = useState(false)
  const action = useAsyncAction(options.fallbackError)

  const check = useCallback(
    (next: V) => {
      const result = schema.safeParse(next)
      return result.success ? {} : toErrors(result.error)
    },
    [schema],
  )

  const setValue = <K extends keyof V & string>(key: K, value: V[K]) => {
    const next = { ...values, [key]: value }
    setValues(next)
    if (submitted) setErrors(check(next))
    else if (errors[key]) setErrors((prev) => ({ ...prev, [key]: "" }))
  }
  const blur = (key: keyof V & string) => {
    if (values[key] === "" && !submitted) return
    const found = check(values)[key] ?? ""
    setErrors((prev) => ({ ...prev, [key]: found }))
  }
  const handleSubmit =
    (onValid: (values: V) => Promise<void>) =>
    async (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      setSubmitted(true)
      const found = check(values)
      setErrors(found)
      if (Object.keys(found).length) return
      await action.run(() => onValid(values))
    }

  return {
    values,
    errors,
    setValue,
    blur,
    handleSubmit,
    pending: action.pending,
    formError: action.error,
    run: action.run,
    /** 校验单个字段并返回是否通过（用于「发送验证码」前校验手机号） */
    validateField: (key: keyof V & string) => {
      const found = check(values)[key] ?? ""
      setSubmitted(true)
      setErrors((prev) => ({ ...prev, [key]: found }))
      return !found
    },
  }
}

export { errorMessage, useAsyncAction, useAuthForm }
export type { FieldErrors }

"use client"

import {
  useEffect,
  useState,
  type CSSProperties,
  type ComponentProps,
  type ReactNode,
} from "react"
import { motion, useReducedMotion } from "motion/react"
import { cva } from "class-variance-authority"
import { MessageSquare } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetTitle } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"
import {
  AgentChatProvider,
  useAgentChat,
  useAgentContext,
} from "./agent-chat-context"
import { AgentChatBody } from "./agent-chat-body"
import { useAgentChatPosition } from "./use-agent-chat-position"
import type { AgentChatMode } from "./types"
import type { AgentChatLabels } from "./config"

const agentChatTriggerVariants = cva("", {
  variants: {
    variant: {
      fab: "fixed right-4 bottom-4 z-40 size-12 rounded-full shadow-lg",
      button: "",
    },
  },
})

function AgentChatTrigger({
  className,
  variant = "fab",
  ...props
}: Omit<ComponentProps<typeof Button>, "variant"> & {
  variant?: "fab" | "button"
}) {
  const { open, setOpen, mode, labels } = useAgentContext()
  if (variant === "fab" && (mode !== "floating" || open)) return null
  return (
    <Button
      data-slot="agent-chat-trigger"
      data-state={open ? "open" : "closed"}
      data-mode={mode}
      className={cn(agentChatTriggerVariants({ variant }), className)}
      variant={variant === "fab" ? "default" : "outline"}
      size={variant === "fab" ? "icon" : "sm"}
      aria-label={open ? labels.closeTrigger : labels.openTrigger}
      aria-expanded={open}
      {...props}
      onClick={(event) => {
        props.onClick?.(event)
        if (!event.defaultPrevented) setOpen(!open)
      }}
    >
      <MessageSquare />
      {variant === "button" ? labels.title : null}
    </Button>
  )
}

/** 从工作区发起一个上下文问题，仍使用 Provider 中的同一段会话。 */
function AgentChatSuggestion({
  question,
  children,
  className,
  ...props
}: ComponentProps<typeof Button> & { question: string; children?: ReactNode }) {
  const { chat, setOpen, updateScroll } = useAgentContext()
  const busy = chat.status === "streaming" || chat.status === "submitted"
  return (
    <Button
      data-slot="agent-chat-suggestion"
      variant="link"
      className={className}
      {...props}
      disabled={busy || props.disabled}
      onClick={(event) => {
        props.onClick?.(event)
        if (event.defaultPrevented) return
        setOpen(true)
        updateScroll({ follow: true })
        void chat.sendMessage({ text: question })
      }}
    >
      {children ?? question}
    </Button>
  )
}

function AgentChatPanel({
  className,
  id,
  draggable = true,
}: Pick<ComponentProps<"aside">, "className" | "id"> & {
  /**
   * 桌面浮动模式下是否允许拖动面板；小于 768px 的 Sheet 始终不可拖动
   * @default true
   */
  draggable?: boolean
}) {
  const { mode, open, setOpen, title, labels } = useAgentContext()
  const [mobile, setMobile] = useState(false)
  const [width, setWidth] = useState(400)
  const reduced = useReducedMotion()
  const movable = mode === "floating" && !mobile && draggable
  const { panelRef, position, headerProps, onMoveKeyDown, reset } =
    useAgentChatPosition({
      enabled: movable && open,
      active: mode === "floating" && !mobile && open,
    })
  useEffect(() => {
    const query = window.matchMedia("(max-width: 767px)")
    const update = () => setMobile(query.matches)
    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])
  if (!open) return null
  if (mobile)
    return (
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent
          id={id}
          data-slot="agent-chat-panel"
          data-mode={mode}
          data-state="open"
          side="bottom"
          showCloseButton={false}
          className={cn(
            "h-[92dvh]! max-h-[92dvh] gap-0 rounded-t-2xl motion-reduce:transition-none",
            className,
          )}
        >
          <SheetTitle className="sr-only">{title}</SheetTitle>
          <AgentChatBody />
        </SheetContent>
      </Sheet>
    )
  return (
    <motion.aside
      ref={panelRef}
      data-draggable={movable || undefined}
      id={id}
      data-slot="agent-chat-panel"
      data-state="open"
      aria-label={title}
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault()
          setOpen(false)
        }
      }}
      data-mode={mode}
      initial={reduced ? false : { opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: reduced ? 0 : 0.2 }}
      style={
        {
          "--agent-width": `${width}px`,
          ...(mode === "floating" && position
            ? {
                left: position.x,
                top: position.y,
                right: "auto",
                bottom: "auto",
              }
            : {}),
        } as CSSProperties
      }
      className={cn(
        "flex min-h-0 flex-col bg-background text-foreground data-[dragging]:cursor-grabbing data-[dragging]:select-none",
        mode === "embedded"
          ? "relative h-full w-(--agent-width) shrink-0 border-l border-edge"
          : "fixed right-4 bottom-4 z-40 h-[min(600px,calc(100dvh-2rem))] w-[400px] max-w-[calc(100vw-2rem)] overflow-hidden rounded-2xl border border-edge shadow-xl",
        className,
      )}
    >
      {mode === "embedded" ? (
        <div
          data-slot="agent-chat-resize-handle"
          role="separator"
          aria-label={labels.resize}
          aria-orientation="vertical"
          aria-valuemin={320}
          aria-valuemax={640}
          aria-valuenow={width}
          tabIndex={0}
          className="absolute inset-y-0 -left-1 w-2 cursor-col-resize touch-none rounded select-none focus-visible:bg-primary/20 focus-visible:outline-none"
          onKeyDown={(event) => {
            if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
              event.preventDefault()
              setWidth((value) =>
                Math.max(
                  320,
                  Math.min(640, value + (event.key === "ArrowLeft" ? 16 : -16)),
                ),
              )
            }
          }}
          onPointerDown={(event) => {
            event.currentTarget.setPointerCapture(event.pointerId)
            event.preventDefault()
          }}
          onPointerMove={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId))
              setWidth(
                Math.max(
                  320,
                  Math.min(
                    640,
                    event.currentTarget.parentElement!.getBoundingClientRect()
                      .right - event.clientX,
                  ),
                ),
              )
          }}
          onPointerUp={(event) => {
            event.currentTarget.releasePointerCapture(event.pointerId)
          }}
        />
      ) : null}
      <AgentChatBody
        draggable={movable}
        headerProps={headerProps}
        onMoveKeyDown={onMoveKeyDown}
        onResetPosition={reset}
      />
    </motion.aside>
  )
}

