import { isToolUIPart, getToolName, type UIMessage } from "ai"
import {
  Brain,
  Check,
  Copy,
  ExternalLink,
  LoaderCircle,
  RotateCcw,
  ThumbsDown,
  ThumbsUp,
  X,
} from "lucide-react"
import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Button } from "@/components/ui/button"
import { CodeBlock, CodeBlockContent } from "@/components/ui/code-block"
import { Message, MessageContent, MessageFooter } from "@/components/ui/message"
import {
  Trace,
  TraceCollapsible,
  TraceCollapsibleContent,
  TraceCollapsibleTrigger,
  TraceIcon,
  TraceLine,
  TraceTitle,
} from "@/components/ui/trace"

function messageText(message: UIMessage) {
  return message.parts
    .filter((part) => part.type === "text")
    .map((part) => part.text)
    .join("")
}

function AgentChatReasoning({
  text,
  running,
  interrupted,
}: {
  text: string
  running: boolean
  interrupted: boolean
}) {
  const { labels } = useAgentContext()
  const [seconds, setSeconds] = useState(0)
  useEffect(() => {
    if (!running) return
    const started = Date.now()
    const timer = setInterval(
      () => setSeconds((Date.now() - started) / 1000),
      100,
    )
    return () => clearInterval(timer)
  }, [running])
  return (
    <TraceCollapsible data-slot="agent-chat-reasoning">
      <TraceCollapsibleTrigger>
        <TraceLine status={running ? "running" : undefined}>
          <TraceIcon>
            {running ? (
              <LoaderCircle className="animate-spin motion-reduce:animate-none" />
            ) : (
              <Brain />
            )}
          </TraceIcon>
          <TraceTitle>
            {running
              ? labels.thinking
              : interrupted
                ? labels.thinkingStopped
                : seconds === 0
                  ? labels.reasoningSummary
                  : labels.thought.replace(
                      "{seconds}",
                      new Intl.NumberFormat(undefined, {
                        maximumFractionDigits: 1,
                      }).format(seconds),
                    )}
          </TraceTitle>
        </TraceLine>
      </TraceCollapsibleTrigger>
      <TraceCollapsibleContent>
        <p className="text-sm leading-7">{text || labels.preparing}</p>
      </TraceCollapsibleContent>
    </TraceCollapsible>
  )
}
function safeSource(url: string) {
  try {
    const parsed = new URL(url)
    return ["https:", "http:"].includes(parsed.protocol)
      ? parsed.href
      : undefined
  } catch {
    return undefined
  }
}

function AgentChatMessage({
  message,
  live,
  busy,
  regenerate,
}: {
  message: UIMessage
  live: boolean
  busy: boolean
  regenerate: () => void
}) {
  const { labels } = useAgentContext()
  const [feedback, setFeedback] = useState<"up" | "down" | null>(null)
  const [notice, setNotice] = useState("")
  const text = messageText(message)
  if (message.role === "user")
    return (
      <Message data-slot="agent-chat-message" data-role="user" align="end">
        <MessageContent>
          <Bubble align="end" variant="muted">
            <BubbleContent>{text}</BubbleContent>
          </Bubble>
        </MessageContent>
      </Message>
    )
  return (
    <Message
      data-slot="agent-chat-message"
      data-role="assistant"
      data-state={live ? "streaming" : "idle"}
    >
      <MessageContent className="gap-4">
        <Trace>
          {message.parts.map((part, index) => {
            if (part.type === "reasoning")
              return (
                <AgentChatReasoning
                  key={index}
                  text={part.text}
                  running={live && part.state === "streaming"}
                  interrupted={!live && part.state === "streaming"}
                />
              )
            if (isToolUIPart(part)) {
              const done = part.state === "output-available"
              const failed =
                part.state === "output-error" || part.state === "output-denied"
              const running = live && !done && !failed
              const label = `${running ? labels.running : done ? labels.completed : failed ? labels.failed : labels.stopped} · ${getToolName(part)}`
              return (
                <TraceCollapsible key={part.toolCallId}>
                  <TraceCollapsibleTrigger>
                    <TraceLine
                      status={
                        running ? "running" : failed ? "error" : undefined
                      }
                    >
                      <TraceIcon>
                        {running ? (
                          <LoaderCircle className="animate-spin motion-reduce:animate-none" />
                        ) : done ? (
                          <Check />
                        ) : (
                          <X />
                        )}
                      </TraceIcon>
                      <TraceTitle>{label}</TraceTitle>
                    </TraceLine>
                  </TraceCollapsibleTrigger>
                  <TraceCollapsibleContent>
                    <div className="flex flex-col gap-2">
                      <p className="text-xs">{labels.toolInput}</p>
                      <CodeBlock size="sm">
                        <CodeBlockContent wrap>
                          {JSON.stringify(part.input ?? {}, null, 2)}
                        </CodeBlockContent>
                      </CodeBlock>
                      <p className="text-xs">{labels.toolOutput}</p>
                      <CodeBlock
                        size="sm"
                        variant={failed ? "destructive" : "default"}
                      >
                        <CodeBlockContent wrap>
                          {part.state === "output-error"
                            ? part.errorText
                            : done
                              ? JSON.stringify(part.output, null, 2)
                              : part.state === "output-denied"
                                ? labels.denied
                                : running
                                  ? labels.waiting
                                  : labels.incomplete}
                        </CodeBlockContent>
                      </CodeBlock>
                    </div>
                  </TraceCollapsibleContent>
                </TraceCollapsible>
              )
            }
            if (part.type === "source-url") {
              const href = safeSource(part.url)
              return href ? (
                <a
                  key={part.sourceId}
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <TraceLine>
                    <TraceIcon>
                      <ExternalLink />
                    </TraceIcon>
                    <TraceTitle>
                      {part.title ?? new URL(href).hostname}
                      <span className="sr-only">{labels.newTab}</span>
                    </TraceTitle>
                  </TraceLine>
                </a>
              ) : null
            }
            return null
          })}
        </Trace>
        {text ? (
          <Bubble variant="ghost">
            <BubbleContent>
              <AgentChatMarkdown text={text} />
            </BubbleContent>
          </Bubble>
        ) : null}
        {!live ? (
          <MessageFooter className="flex-wrap gap-1">
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.copy}
              disabled={!text}
              onClick={async () => {
                try {
                  await navigator.clipboard.writeText(text)
                  setNotice(labels.copied)
                } catch {
                  setNotice(labels.copyFailed)
                }
              }}
            >
              {notice === labels.copied ? <Check /> : <Copy />}
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.useful}
              aria-pressed={feedback === "up"}
              onClick={() => {
                setFeedback(feedback === "up" ? null : "up")
                setNotice(labels.feedback)
              }}
            >
              <ThumbsUp />
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.notUseful}
              aria-pressed={feedback === "down"}
              onClick={() => {
                setFeedback(feedback === "down" ? null : "down")
                setNotice(labels.feedback)
              }}
            >
              <ThumbsDown />
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={labels.regenerate}
              disabled={busy}
              onClick={regenerate}
            >
              <RotateCcw />
            </Button>
            <span role="status" className="text-xs">
              {notice}
            </span>
          </MessageFooter>
        ) : null}
      </MessageContent>
    </Message>
  )
}

