type AppShellLabels = { [Key in keyof typeof DEFAULT_LABELS]: string }

/** 合并用户传入的文案与默认文案。 */
function resolveLabels(labels?: Partial<AppShellLabels>): AppShellLabels {
  return { ...DEFAULT_LABELS, ...labels }
}

/**
 * 把文案里的占位符替换成实际值。
 * 传字符串时等价于替换 `{name}`（保持早期写法可用）；传对象可一次替换多个，如 `{ count: 3 }`。
 */
function formatLabel(
  template: string,
  values: string | Record<string, string | number>,
): string {
  if (typeof values === "string") return template.replace("{name}", values)
  return Object.entries(values).reduce(
    (text, [key, value]) => text.replaceAll(`{${key}}`, String(value)),
    template,
  )
}

/** AppShell 向下提供的文案，让主区域里的页面组件也能拿到同一套覆盖值。 */
const AppShellLabelsContext = createContext<Partial<AppShellLabels> | undefined>(
  undefined,
)

function AppShellLabelsProvider({
  labels,
  children,
}: {
  labels?: Partial<AppShellLabels>
  children: ReactNode
}) {
  // 本文件是 .ts（不含 JSX），用 createElement 渲染 Provider
  return createElement(AppShellLabelsContext.Provider, { value: labels }, children)
}

/**
 * 读取当前文案：组件自己的 labels > AppShell 提供的 labels > DEFAULT_LABELS。
 * 页面组件（PageHeader、PageToolbar 等）放在 AppShell 里时会自动继承 AppShell 的文案。
 */
function useAppShellLabels(labels?: Partial<AppShellLabels>): AppShellLabels {
  const inherited = useContext(AppShellLabelsContext)
  return resolveLabels({ ...inherited, ...labels })
}

export {
  AppShellLabelsProvider,
  DEFAULT_LABELS,
  DEFAULT_STORAGE_KEY,
  NAV_WIDTH_CLASS,
  NAV_WIDTH_TRANSITION,
  formatLabel,
  resolveLabels,
  useAppShellLabels,
}
export type { AppShellLabels }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"

import * as React from "react"
import {
  motion,
  useInView,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  type MotionValue,
} from "motion/react"

import { cn } from "@/lib/utils"

import {
  buildIsometricModel,
  rotateShapes,
  wallPath,
  type IsometricPoint,
  type IsometricShape,
  type IsometricWall,
} from "./geometry"

/** 按下 / 弹起共用的弹簧，手感接近真实按键。 */
const PRESS_SPRING = { stiffness: 200, damping: 18, mass: 0.5 }
/** 高光跟随鼠标的弹簧，比按下更“跟手”。 */
const LIGHT_SPRING = { stiffness: 300, damping: 30, mass: 0.1 }

type IsometricMarkProps = Omit<React.ComponentProps<"svg">, "children"> & {
  /**
   * 平面形状，坐标是平面 logo 自己的坐标（y 向下）。
   * 请在组件外定义为常量，每次渲染传入新数组会重新计算几何。
   */
  shapes: readonly IsometricShape[]
  /**
   * 投影前绕图形中心旋转的角度（度），用来选择图形平躺在地上的朝向。
   * 取 90 的整数倍时图形的横竖边始终沿等轴测斜轴，看起来是一块平放的板；
   * 传 -90 时原图的横向沿右上方延伸、竖向沿右下方延伸，最接近“正着读”。
   * @default 0
   */
  rotation?: number
  /** 挤出高度，默认取图形平面尺寸的 12% */
  depth?: number
  /** 按下后的挤出高度，默认是 `depth` 的一半 */
  pressedDepth?: number
  /**
   * 点击 / 触摸时是否有按下效果
   * @default true
   */
  interactive?: boolean
  /**
   * 线条是否有跟随鼠标的高光；触屏与“减少动态效果”下自动关闭
   * @default true
   */
  highlight?: boolean
  /**
   * 是否显示背景里沿等轴测方向延伸的虚线辅助线
   * @default false
   */
  guides?: boolean
  /** 可访问名称；不传时整个图形对读屏隐藏 */
  label?: string
}

/** 单面侧墙：高度由弹簧驱动，墙路径随高度重算，顶边始终贴着顶面。 */
function IsometricMarkWall({
  wall,
  height,
  gradientId,
}: {
  wall: IsometricWall
  height: MotionValue<number>
  gradientId: string
}) {
  const d = useTransform(height, (h) => wallPath(wall, h))

  // 同一面先画底色线再画高光线，后画的近处面会盖住远处面的线
  return (
    <g data-slot="isometric-mark-wall">
      <motion.path d={d} className="fill-background" stroke="var(--stroke)" />
      <motion.path d={d} fill="none" stroke={`url(#${gradientId})`} />
    </g>
  )
}

/** 把平面多边形挤出成等轴测线条 3D，带斜纹顶面、跟随鼠标的高光与按下效果。 */
function IsometricMark({
  shapes,
  rotation = 0,
  depth: depthProp,
  pressedDepth,
  interactive = true,
  highlight = true,
  guides = false,
  label,
  className,
  ref,
  onPointerDown,
  onPointerUp,
  onPointerCancel,
  onPointerLeave,
  ...props
}: IsometricMarkProps) {
  const id = React.useId()
  const patternId = `isometric-mark-pattern-${id}`
  const gradientId = `isometric-mark-light-${id}`

  const model = React.useMemo(
    () => buildIsometricModel(rotateShapes(shapes, rotation), depthProp),
    [shapes, rotation, depthProp],
  )
  const { viewBox, unit, depth } = model
  const pressedHeight = pressedDepth ?? depth / 2

  const rootRef = React.useRef<SVGSVGElement | null>(null)
  const setRef = React.useCallback(
    (node: SVGSVGElement | null) => {
      rootRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) ref.current = node
    },
    [ref],
  )

  const reduceMotion = useReducedMotion()
  const inView = useInView(rootRef, { margin: "80px" })

  // 当前挤出高度；顶面整体下移 depth - height，侧墙按 height 重算
  const [pressed, setPressed] = React.useState(false)
  const height = useSpring(depth, PRESS_SPRING)
  React.useEffect(() => {
    const target = pressed ? pressedHeight : depth
    if (reduceMotion) height.jump(target)
    else height.set(target)
  }, [pressed, pressedHeight, depth, reduceMotion, height])
  // 用 y 偏移而不是 transform 字符串，斜纹才会跟着轮廓一起走
  const topOffset = useTransform(height, (h) => depth - h)

  // 高光：鼠标在窗口中的相对位置映射到 viewBox
  const mouseX = useMotionValue(0.5)
  const mouseY = useMotionValue(0.5)
  const lightX = useSpring(
    useTransform(mouseX, [0, 1], [viewBox.x, viewBox.x + viewBox.width]),
    LIGHT_SPRING,
  )
  const lightY = useSpring(
    useTransform(mouseY, [0, 1], [viewBox.y, viewBox.y + viewBox.height]),
    LIGHT_SPRING,
  )
  React.useEffect(() => {
    if (!highlight || reduceMotion || !inView) return
    if (window.matchMedia("(hover: none)").matches) return

    const handleMouseMove = (event: MouseEvent) => {
      mouseX.set(event.clientX / window.innerWidth)
      mouseY.set(event.clientY / window.innerHeight)
    }
    window.addEventListener("mousemove", handleMouseMove, { passive: true })
    return () => window.removeEventListener("mousemove", handleMouseMove)
  }, [highlight, reduceMotion, inView, mouseX, mouseY])

  const release = () => setPressed(false)
  const hatch = unit * 10

  return (
    <svg
      ref={setRef}
      data-slot="isometric-mark"
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
      fill="none"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn(
        "block h-auto w-full touch-manipulation overflow-visible [--guide:color-mix(in_oklab,var(--foreground)_14%,transparent)] [--pattern:color-mix(in_oklab,var(--foreground)_12%,var(--background))] [--stroke:color-mix(in_oklab,var(--foreground)_16%,var(--background))]",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event)
        if (interactive) setPressed(true)
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event)
        release()
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        release()
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event)
        release()
      }}
      {...props}
    >
      <defs>
        <pattern
          id={patternId}
          width={hatch}
          height={hatch}
          patternUnits="userSpaceOnUse"
        >
          <path
            d={`M${-unit} ${unit}l${unit * 2} ${-unit * 2}M0 ${hatch}l${hatch} ${-hatch}M${hatch - unit} ${hatch + unit}l${unit * 2} ${-unit * 2}`}
            stroke="var(--pattern)"
            strokeWidth={unit}
          />
        </pattern>

        <motion.radialGradient
          id={gradientId}
          cx={lightX}
          cy={lightY}
          r={unit * 200}
          gradientUnits="userSpaceOnUse"
        >
          <stop stopColor="var(--foreground)" stopOpacity="0.7" />
          <stop offset="1" stopColor="var(--foreground)" stopOpacity="0" />
        </motion.radialGradient>
      </defs>

      {guides ? (
        <path
          data-slot="isometric-mark-guides"
          d={model.guides}
          stroke="var(--guide)"
          strokeWidth={unit}
          strokeDasharray={`${unit * 4} ${unit * 2}`}
        />
      ) : null}

      <g
        strokeWidth={unit}
        strokeLinejoin="round"
        strokeLinecap="round"
        fillRule="evenodd"
      >
        {model.walls.map((wall, index) => (
          <IsometricMarkWall
            key={index}
            wall={wall}
            height={height}
            gradientId={gradientId}
          />
        ))}

        <motion.g data-slot="isometric-mark-top" style={{ y: topOffset }}>
          <path d={model.top} className="fill-background" />
          <path d={model.top} fill={`url(#${patternId})`} />
          <path d={model.top} stroke="var(--stroke)" />
          <path d={model.top} stroke={`url(#${gradientId})`} />
        </motion.g>
      </g>
    </svg>
  )
}

export { IsometricMark }
export type { IsometricMarkProps, IsometricPoint, IsometricShape }

/**
 * 等轴测挤出的纯几何计算：只依赖数学，不碰 React，方便单测与复用。
 *
 * 坐标约定：平面 logo 的坐标 (x, y)，y 向下；挤出方向为 z（向上）。
 * 投影：X = (x - y)·cos30°，Y = (x + y)·sin30° - z。
 * 在这个投影下，观察者位于 (+x, +y, +z) 一侧，朝向 (1, 1) 的墙面可见。
 */

/** 平面坐标点 `[x, y]` */
type IsometricPoint = readonly [number, number]

/** 一个平面形状：一圈外轮廓加若干个孔，孔会被挤成通孔。 */
type IsometricShape = {
  outer: readonly IsometricPoint[]
  holes?: readonly (readonly IsometricPoint[])[]
}

/** 墙面底边在屏幕上的两个端点（z = 0），顶边由当前高度决定。 */
type IsometricWall = { x0: number; y0: number; x1: number; y1: number }

type IsometricModel = {
  viewBox: { x: number; y: number; width: number; height: number }
  /** 线宽、斜纹、虚线等“一个像素”对应的 viewBox 长度，随图形尺寸等比缩放 */
  unit: number
  /** 实际使用的挤出高度（props 未传时为自动值） */
  depth: number
  /** 顶面路径（z = depth），外轮廓与孔都在其中，需配合 evenodd */
  top: string
  /** 可见侧墙，按从远到近排好序 */
  walls: IsometricWall[]
  /** 背景辅助线路径（z = 0） */
  guides: string
}

const COS30 = Math.cos(Math.PI / 6)
const SIN30 = 0.5
const EPSILON = 1e-6
/** 自动挤出高度占图形平面尺寸的比例 */
const AUTO_DEPTH_RATIO = 0.12

const fmt = (n: number) => String(Math.round(n * 100) / 100)

function project(x: number, y: number, z = 0): [number, number] {
  return [(x - y) * COS30, (x + y) * SIN30 - z]
}

/** 去掉首尾重复的闭合点，统一成不含重复端点的环。 */
function cleanRing(ring: readonly IsometricPoint[]): IsometricPoint[] {
  const points = [...ring]
  const first = points[0]
  const last = points[points.length - 1]
  if (points.length > 1 && first[0] === last[0] && first[1] === last[1]) {
    points.pop()
  }
  return points
}

function signedArea(ring: readonly IsometricPoint[]) {
  let sum = 0
  for (let i = 0; i < ring.length; i++) {
    const [x0, y0] = ring[i]
    const [x1, y1] = ring[(i + 1) % ring.length]
    sum += x0 * y1 - x1 * y0
  }
  return sum / 2
}

/** 外轮廓取正面积、孔取负面积，这样所有环的“实体外侧”法线公式一致。 */
function orient(ring: IsometricPoint[], positive: boolean) {
  return signedArea(ring) > 0 === positive ? ring : [...ring].reverse()
}

function ringPath(ring: readonly IsometricPoint[], z: number) {
  return (
    ring
      .map(([x, y], i) => {
        const [px, py] = project(x, y, z)
        return `${i === 0 ? "M" : "L"}${fmt(px)} ${fmt(py)}`
      })
      .join("") + "Z"
  )
}

type Segment = {
  /** 平面坐标，用于排序 */
  px: number
  py: number
  qx: number
  qy: number
}

/** 排序键：沿观察方向的“深度”，越大越靠近观察者。 */
const depthOf = (s: Segment) => (s.px + s.py + s.qx + s.qy) / 4

/**
 * 判断两面墙的前后关系：-1 表示 a 在 b 后面（先画 a），1 相反，0 表示互不遮挡。
 * 墙在屏幕上只有 X = x - y 方向的范围，范围不重叠就不会互相遮挡；
 * 重叠区间内两线段不相交，因此取区间中点比较 x + y 即可。
 */
function compareSegments(a: Segment, b: Segment) {
  const ua0 = a.px - a.py
  const ua1 = a.qx - a.qy
  const ub0 = b.px - b.py
  const ub1 = b.qx - b.qy
  const lo = Math.max(Math.min(ua0, ua1), Math.min(ub0, ub1))
  const hi = Math.min(Math.max(ua0, ua1), Math.max(ub0, ub1))
  if (hi - lo < EPSILON) return 0

  const u = (lo + hi) / 2
  const depthAt = (s: Segment, u0: number, u1: number) => {
    const t = (u - u0) / (u1 - u0)
    return s.px + s.py + t * (s.qx + s.qy - s.px - s.py)
  }
  const diff = depthAt(a, ua0, ua1) - depthAt(b, ub0, ub1)
  if (Math.abs(diff) < EPSILON) return 0
  return diff < 0 ? -1 : 1
}

/**
 * 画家算法的顺序：先按“谁挡住谁”做拓扑排序，凹多边形也能排对；
 * 理论上不会出现环，真遇到时退回按深度最小者优先，保证一定有结果。
 * 顺序只取决于平面形状，与挤出高度无关，所以按下动画时不用重排。
 */
function sortBackToFront(segments: Segment[]) {
  const n = segments.length
  const after: number[][] = Array.from({ length: n }, () => [])
  const blockers = new Array<number>(n).fill(0)

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const order = compareSegments(segments[i], segments[j])
      if (order < 0) {
        after[i].push(j)
        blockers[j]++
      } else if (order > 0) {
        after[j].push(i)
        blockers[i]++
      }
    }
  }

  const done = new Array<boolean>(n).fill(false)
  const sorted: Segment[] = []
  for (let k = 0; k < n; k++) {
    let pick = -1
    for (let i = 0; i < n; i++) {
      if (done[i] || blockers[i] > 0) continue
      if (pick < 0 || depthOf(segments[i]) < depthOf(segments[pick])) pick = i
    }
    if (pick < 0) {
      for (let i = 0; i < n; i++) {
        if (done[i]) continue
        if (pick < 0 || depthOf(segments[i]) < depthOf(segments[pick])) pick = i
      }
    }
    done[pick] = true
    sorted.push(segments[pick])
    for (const next of after[pick]) blockers[next]--
  }
  return sorted
}

function buildIsometricModel(
  shapes: readonly IsometricShape[],
  depthOption?: number,
): IsometricModel {
  const rings: { ring: IsometricPoint[]; hole: boolean }[] = []
  for (const shape of shapes) {
    rings.push({ ring: orient(cleanRing(shape.outer), true), hole: false })
    for (const hole of shape.holes ?? []) {
      rings.push({ ring: orient(cleanRing(hole), false), hole: true })
    }
  }

  // 平面包围盒，用于自动高度与辅助线
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const { ring } of rings) {
    for (const [x, y] of ring) {
      minX = Math.min(minX, x)
      minY = Math.min(minY, y)
      maxX = Math.max(maxX, x)
      maxY = Math.max(maxY, y)
    }
  }
  if (!rings.length) {
    minX = minY = maxX = maxY = 0
  }
  const planSize = Math.max(maxX - minX, maxY - minY, 1)
  const depth = Math.max(depthOption ?? planSize * AUTO_DEPTH_RATIO, 0)

  // 背面剔除：法线 (ey, -ex) 与观察方向 (1, 1) 同侧才可见；
  // 法线与观察方向垂直的墙在屏幕上是一条竖线，面积为零，也不画。
  const segments: Segment[] = []
  for (const { ring } of rings) {
    for (let i = 0; i < ring.length; i++) {
      const [px, py] = ring[i]
      const [qx, qy] = ring[(i + 1) % ring.length]
      if (qy - py - (qx - px) > EPSILON) segments.push({ px, py, qx, qy })
    }
  }
  const walls = sortBackToFront(segments).map((s) => {
    const [x0, y0] = project(s.px, s.py)
    const [x1, y1] = project(s.qx, s.qy)
    return { x0, y0, x1, y1 }
  })

  // 投影后的包围盒：顶面在 z = depth（最高），底边在 z = 0（最低）
  let bx0 = Infinity
  let by0 = Infinity
  let bx1 = -Infinity
  let by1 = -Infinity
  for (const { ring } of rings) {
    for (const [x, y] of ring) {
      const [px, py] = project(x, y)
      bx0 = Math.min(bx0, px)
      bx1 = Math.max(bx1, px)
      by0 = Math.min(by0, py - depth)
      by1 = Math.max(by1, py)
    }
  }
  if (!rings.length) {
    bx0 = by0 = bx1 = by1 = 0
  }
  const size = Math.max(bx1 - bx0, by1 - by0, 1)
  const margin = size * 0.02

  const reach = planSize * 1.2
  const line = (x0: number, y0: number, x1: number, y1: number) => {
    const [ax, ay] = project(x0, y0)
    const [bx, by] = project(x1, y1)
    return `M${fmt(ax)} ${fmt(ay)}L${fmt(bx)} ${fmt(by)}`
  }
  const guides = [
    line(minX, minY - reach, minX, maxY + reach),
    line(maxX, minY - reach, maxX, maxY + reach),
    line(minX - reach, minY, maxX + reach, minY),
    line(minX - reach, maxY, maxX + reach, maxY),
  ].join("")

  return {
    viewBox: {
      x: bx0 - margin,
      y: by0 - margin,
      width: bx1 - bx0 + margin * 2,
      height: by1 - by0 + margin * 2,
    },
    unit: size / 500,
    depth,
    top: rings.map(({ ring }) => ringPath(ring, depth)).join(""),
    walls,
    guides,
  }
}

/** 高度为 h 时一面墙的路径：底边固定在 z = 0，顶边抬到 z = h。 */
function wallPath({ x0, y0, x1, y1 }: IsometricWall, h: number) {
  return `M${fmt(x0)} ${fmt(y0 - h)}L${fmt(x1)} ${fmt(y1 - h)}L${fmt(x1)} ${fmt(y1)}L${fmt(x0)} ${fmt(y0)}Z`
}

/**
 * 投影前把平面形状绕包围盒中心旋转 `degrees` 度（y 向下坐标系里顺时针为正）。
 * 建议取 90 的整数倍：这样图形的横竖边始终沿等轴测斜轴，仍是一块平放的板；
 * 其他角度（如 -45°）会让顶面看起来像一堵立着的墙。
 */
function rotateShapes(
  shapes: readonly IsometricShape[],
  degrees: number,
): IsometricShape[] {
  if (!degrees) return shapes.map((s) => ({ ...s }))
  const all = shapes.flatMap((s) => [...s.outer, ...(s.holes ?? []).flat()])
  const xs = all.map(([x]) => x)
  const ys = all.map(([, y]) => y)
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2
  const cy = (Math.min(...ys) + Math.max(...ys)) / 2
  const r = (degrees * Math.PI) / 180
  const cos = Math.cos(r)
  const sin = Math.sin(r)
  const turn = (ring: readonly IsometricPoint[]): IsometricPoint[] =>
    ring.map(([x, y]) => [
      cx + (x - cx) * cos - (y - cy) * sin,
      cy + (x - cx) * sin + (y - cy) * cos,
    ])
  return shapes.map((s) => ({
    outer: turn(s.outer),
    holes: s.holes?.map(turn),
  }))
}

export { buildIsometricModel, rotateShapes, wallPath }
export type { IsometricModel, IsometricPoint, IsometricShape, IsometricWall }
